def md5(b):
    return hashlib.md5(b).hexdigest()


def build(rel, src_bytes, want_from, edits):
    if md5(src_bytes) != want_from:
        raise SystemExit("REFUSED: %s is %s, not the FROM pin %s" % (rel, md5(src_bytes)[:8], want_from[:8]))
    s = src_bytes.decode("utf-8")
    for i, (old, new) in enumerate(edits, 1):
        n = s.count(old)
        if n != 1:
            raise SystemExit("REFUSED: %s anchor %d occurs %d times (must be exactly once)" % (rel, i, n))
        s = s.replace(old, new, 1)
    return s.encode("utf-8")


def main():
    if len(sys.argv) != 3:
        raise SystemExit(__doc__)
    root, outdir = sys.argv[1], sys.argv[2]
    for rel, want_from, edits in FILES:
        with open(os.path.join(root, rel), "rb") as fh:
            out = build(rel, fh.read(), want_from, edits)
        dst = os.path.join(outdir, rel)
        os.makedirs(os.path.dirname(dst), exist_ok=True)
        with open(dst, "wb") as fh:
            fh.write(out)
        print("built %s %s -> %s (%d edits)" % (rel, want_from[:8], md5(out)[:8], len(edits)))


if __name__ == "__main__":
    main()
